#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
in highp vec4 in_POSITION0;
in highp vec2 in_TEXCOORD0;
out highp vec2 vs_TEXCOORD0;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec2 _FoldOrigin;
uniform 	vec2 _FoldDir;
uniform 	float _FoldDist;
uniform 	float _IsBack;
uniform 	float _ShadowStrength;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
in highp vec2 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
vec2 u_xlat0;
mediump vec4 u_xlat16_0;
mediump vec4 u_xlat16_1;
bvec2 u_xlatb1;
float u_xlat2;
vec2 u_xlat3;
int u_xlati3;
float u_xlat6;
int u_xlati6;
bvec2 u_xlatb6;
float u_xlat9;
int op_not(int value) { return -value - 1; }
ivec2 op_not(ivec2 a) { a.x = op_not(a.x); a.y = op_not(a.y); return a; }
ivec3 op_not(ivec3 a) { a.x = op_not(a.x); a.y = op_not(a.y); a.z = op_not(a.z); return a; }
ivec4 op_not(ivec4 a) { a.x = op_not(a.x); a.y = op_not(a.y); a.z = op_not(a.z); a.w = op_not(a.w); return a; }

void main()
{
    u_xlat0.xy = vs_TEXCOORD0.xy + (-_FoldOrigin.xy);
    u_xlat0.x = dot(u_xlat0.xy, vec2(_FoldDir.x, _FoldDir.y));
    u_xlat3.x = _FoldDist * 0.5;
    u_xlati3 = int((u_xlat3.x<u_xlat0.x) ? 0xFFFFFFFFu : uint(0));
    u_xlatb6.x = _IsBack<0.5;
    if(u_xlatb6.x){
        u_xlati6 = op_not(u_xlati3);
        if((u_xlati6)!=0){discard;}
        u_xlat16_1 = texture(_MainTex, vs_TEXCOORD0.xy);
        u_xlat6 = (-_FoldDist) * 0.5 + u_xlat0.x;
        u_xlat6 = u_xlat6 * 12.5;
        u_xlat6 = clamp(u_xlat6, 0.0, 1.0);
        u_xlat9 = u_xlat6 * -2.0 + 3.0;
        u_xlat6 = u_xlat6 * u_xlat6;
        u_xlat6 = u_xlat6 * u_xlat9;
        u_xlat9 = (-_ShadowStrength) + 1.0;
        u_xlat2 = (-u_xlat9) + 1.0;
        u_xlat6 = u_xlat6 * u_xlat2 + u_xlat9;
        u_xlat16_1.xyz = vec3(u_xlat6) * u_xlat16_1.xyz;
        SV_Target0 = u_xlat16_1;
        return;
    } else {
        u_xlati3 = op_not(u_xlati3);
        if((u_xlati3)!=0){discard;}
        u_xlat3.xy = vec2(_FoldDir.x, _FoldDir.y) + vec2(_FoldDir.x, _FoldDir.y);
        u_xlat0.x = (-_FoldDist) * 0.5 + u_xlat0.x;
        u_xlat0.xy = (-u_xlat3.xy) * u_xlat0.xx + vs_TEXCOORD0.xy;
        u_xlatb6.xy = lessThan(u_xlat0.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
        u_xlatb1.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
        u_xlatb6.x = u_xlatb6.x || u_xlatb1.x;
        u_xlatb6.x = u_xlatb6.y || u_xlatb6.x;
        u_xlatb6.x = u_xlatb1.y || u_xlatb6.x;
        if(u_xlatb6.x){discard;}
        u_xlat16_0 = texture(_MainTex, u_xlat0.xy);
        SV_Target0.xyz = u_xlat16_0.xyz * vec3(0.800000012, 0.800000012, 0.800000012);
        SV_Target0.w = u_xlat16_0.w;
        return;
    }
    return;
}
